<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateSnippet\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use OpenApi\Attributes as OA;
use Throwable;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\TemplateSnippetRef;
use Civi\Lughauth\Features\Document\TemplateSnippet\Application\Usecase\Create\TemplateSnippetCreateUsecase;
use Civi\Lughauth\Features\Document\TemplateSnippet\Application\Usecase\List\TemplateSnippetListUsecase;
use Civi\Lughauth\Features\Document\TemplateSnippet\Application\Usecase\Update\TemplateSnippetUpdateUsecase;
use Civi\Lughauth\Features\Document\TemplateSnippet\Application\Usecase\Delete\TemplateSnippetDeleteUsecase;
use Civi\Lughauth\Features\Document\TemplateSnippet\Application\Usecase\Retrieve\TemplateSnippetRetrieveUsecase;
use Civi\Lughauth\Features\Document\TemplateSnippet\Application\Usecase\Enable\TemplateSnippetEnableUsecase;
use Civi\Lughauth\Features\Document\TemplateSnippet\Application\Usecase\Disable\TemplateSnippetDisableUsecase;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TemplateSnippetAllowController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly TemplateSnippetCreateUsecase $createUsecase,
        private readonly TemplateSnippetListUsecase $listUsecase,
        private readonly TemplateSnippetUpdateUsecase $updateUsecase,
        private readonly TemplateSnippetDeleteUsecase $deleteUsecase,
        private readonly TemplateSnippetRetrieveUsecase $retrieveUsecase,
        private readonly TemplateSnippetEnableUsecase $enableUsecase,
        private readonly TemplateSnippetDisableUsecase $disableUsecase,
    ) {
    }
    #[OA\Get(
        path: "/api/me/acl/document/template-snippet",
        tags: ["Template snippet access control"],
        description:"Allows",
        responses: [
        new OA\Response(response: 200, description: "Ok"),
    ]
    )
    ]
    public function genericAllow(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Check generic allow for Template snippet");
        $span = $this->startSpan("Generic allow for Template snippet");
        try {
            $value = [
              'allows' => [
                $this->createUsecase->allowCreate(),
                $this->listUsecase->allowList(),
                $this->updateUsecase->allowUpdate(),
              $this->deleteUsecase->allowDelete(),
              $this->retrieveUsecase->allowRetrieve(),
              $this->enableUsecase->allowEnable(),
              $this->disableUsecase->allowDisable(),
              ],
              'fields' => [
                'noEditables' => $this->updateUsecase->fixedFields(),
                'noVisibles' => $this->retrieveUsecase->hiddenFields()
              ]
            ];
            $encoded = json_encode($value);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(200)
                  ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[OA\Get(
        path: "/api/me/acl/document/template-snippet/{uid}",
        tags: ["Template snippet access control"],
        description:"Allows",
        parameters: [
        new OA\PathParameter(name: "uid", required: true, schema: new OA\Schema(type: "string")),
    ],
        responses: [
        new OA\Response(response: 200, description: "Ok"),
        new OA\Response(response: 404, description: "Not found"),
    ]
    )
    ]
    public function contextualAllow(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Check specific allow for Template snippet");
        $span = $this->startSpan("Specific allow for Template snippet");
        try {
            if (!isset($args['uid'])) {
                throw new NotFoundException('-');
            }
            $ref = new TemplateSnippetRef(uid: $args['uid']);
            $value = [
              'allows' => [
                $this->updateUsecase->allowUpdate($ref),
              $this->deleteUsecase->allowDelete($ref),
              $this->retrieveUsecase->allowRetrieve($ref),
              $this->enableUsecase->allowEnable($ref),
              $this->disableUsecase->allowDisable($ref),
              ],
              'fields' => [
                'noEditables' => $this->updateUsecase->fixedFields($ref),
                'noVisibles' => $this->retrieveUsecase->hiddenFields($ref)
              ]
            ];
            $encoded = json_encode($value);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(200)
                  ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
